final case class Order private (cartId: CartId, buyerId: BuyerId, lines: Vector[OrderLine]) {
  def totalInMinorUnits: Money = lines.foldLeft(Money.zero)(_ + _.amount)  // query, no side effect
  def isEmpty: Boolean = lines.isEmpty                                     // boolean accessor
  def cancellable: Boolean = status == OrderStatus.Draft
  def addLine(sku: Sku, quantity: Quantity): Order =                       // returns a new Order
    copy(lines = lines :+ OrderLine(sku, quantity, Money.zero))
}

object Order {
  def forCart(cartId: CartId, buyerId: BuyerId): Order = Order(cartId, buyerId, Vector.empty)
}
